// TH14 synthetic appearance aliases used by this card (see transcribe/th14/bullet-types.md).
// Native etSprite(0,32,6) -> TH14_GLOW_BALL, color 6; etSprite(1,5,13) -> TH14_BALL2, color 13.
const TH14_BALL2: int = 432;
const TH14_GLOW_BALL: int = 880;

// TH14 v1.00b Extra boss 6th spell, st07bs.ecl.txt::BossCard6 (spell 115) lines 1774-1830,
// with dependency BossCard6_at (1832-1885). Source t0 is the first frame after OPENING_BUFFER.
const TIME_LIMIT: int = 3424;      // 120 buffer + (3000 source + 300 tail) + 4 startup
const OPENING_BUFFER: int = 120;
const SOURCE_LIMIT: int = 3000;    // setInterrupt(0,0,$A*60,"Boss7") / spellEx time

// Emitter0 EX: etEx type2(a=1) ANIM spawn retreat folded into sh_dist at fire time.
// Then VELTIME type0x200000 a=60 r=0 (s keeps angle), then VELTIME a=320 r=0.2+RANDF*5.
xformdef C6_BIG(vel: fx) {
    @60 step_speed(0fx, 60 + 65536 * EASE_LINEAR);
    step_speed(vel, 320 + 65536 * EASE_LINEAR);
}
// Emitter1 EX: ANIM(a=1) at speed0 retreats nothing; VELTIME a=320 r=2.0 (s keeps angle).
xformdef C6_SMALL {
    step_speed(2fx, 320 + 65536 * EASE_LINEAR);
}

// BossCard6_at(%C): %C is a FINAL_X snapshot taken once per drum; FINAL_Y is read at every
// emitter offset (the in-flight move target stays 224). 16 rounds, wait(3) each.
sub c6_at(col_x: fx, col_y: fx, base_a: int, gi0: int) {
    var off: fx = 0fx;             // %B, +14 per round
    for i in 0..16 {
        var v0: fx = 0fx;
        if i % 2 != 0 {           // unless ($D & 1) -> odd D uses 1+RANDF*2, even keeps 0
            v0 = 1fx + ((rand(65536) - 32768) as fx / 65536 + 0.5fx) * 2fx;
        }
        sh_reset(0);
        sh_sprite(0, TH14_GLOW_BALL, 6);   // etSprite(0,32,6)
        sh_ring(0, 1);                     // etAim(0,3): fixed ring, N=1
        sh_aim(0, 0);
        sh_count(0, 1, 1);
        sh_angle(0, base_a as angle, 0deg); // etAngle(0,%A,pi) with one ray
        sh_speed(0, v0, 0fx);
        sh_dist(0, -32fx - 4fx * v0);      // etDist(-32) + ANIM position-=4*velocity
        var vel: fx = 0.2fx + ((rand(65536) - 32768) as fx / 65536 + 0.5fx) * 5fx;
        sh_xform(0, C6_BIG(vel));
        sh_offset_abs(0, col_x, col_y + off);  // etOffsetAbs(0,%C,%B+FINAL_Y)
        sh_fire(0);
        sh_offset_abs(0, col_x, col_y - off);  // etOffsetAbs(0,%C,FINAL_Y-%B)
        sh_fire(0);

        sh_reset(1);
        sh_sprite(1, TH14_BALL2, 13);      // etSprite(1,5,13)
        sh_ring(1, 0);                     // etAim(1,1): fixed fan
        sh_aim(1, 0);
        sh_count(1, gi0, 1);               // etCount(1,$GI0,1)
        var aoff: int = (rand(65536) - 32768) / 4; // RANDF2*pi/4 -> +-8192 BAM
        sh_angle(1, (base_a + aoff) as angle, 30deg); // etAngle(1,%A+RANDF2*pi/4,pi/6)
        sh_speed(1, 0fx, 0fx);
        sh_dist(1, -32fx);                 // etDist(-32); ANIM shift is 4*0
        sh_xform(1, C6_SMALL);
        sh_offset_abs(1, col_x, col_y + off);
        sh_fire(1);
        sh_offset_abs(1, col_x, col_y - off);
        sh_fire(1);
        wait(3);
        off = off + 14fx;                  // %B = %B + 14
    }
}

sub c6_wait(frames: int, end_frame: int) {
    for i in 0..frames {
        wait(1);
        if $frame >= end_frame { return; }
    }
}

sub c6_stop() {
    // Source timeout: this card stops firing and does not start Boss7; freeze in place.
    move_to(0, $self_x, $self_y, EASE_LINEAR);
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
}

async sub pattern() {
    wait(OPENING_BUFFER);
    var end_frame: int = $frame + SOURCE_LIMIT;
    // movePosTime(60,4,0,144) right after the entry block; the +60 time gate is this wait.
    move_to(60, 0fx, 144fx, EASE_QUAD_OUT);
    wait(60);
    var b: fx = 170fx;      // %B, flips sign every drum
    var a: int = 32768;     // %C = pi (BAM), +pi every drum
    var d: int = 120;       // $D
    var gi0: int = 1;       // $GI0
    loop {
        c6_wait(60, end_frame);                     // 1813 wait(60)
        if $frame >= end_frame { c6_stop(); return; }
        move_to(60, b, 224fx, EASE_QUAD_IN);        // 1814 movePosTime(60,1,%B,224)
        c6_wait(60, end_frame);                     // 1816 wait(60)
        if $frame >= end_frame { c6_stop(); return; }
        var col_x: fx = b / 3fx;                    // %FINAL_X snapshot of the 40-frame move
        move_to(40, col_x, 224fx, EASE_QUAD_OUT);   // 1818 movePosTime(40,4,%B/3,224)
        c6_at(col_x, 224fx, a, gi0);                // 1819 @BossCard6_at(%C)
        c6_wait(d, end_frame);                      // 1821 wait($D)
        if $frame >= end_frame { c6_stop(); return; }
        if d > 30 { d = d - 10; }                   // 1822-1823, D floors at 30
        gi0 = gi0 + 1;                              // 1825
        b = -b;                                     // 1826
        a = a + 32768;                              // 1820 %C += pi
    }
}

async sub boss_card6() {
    set_invuln(65535);
    set_hitbox(24fx);   // Boss setHitbox(48,48) circle -> r24
    set_hurtbox(24fx);  // Boss setHurtbox(48,48) -> r24
    spell_begin(0, 115, pattern, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 128fx, 3000, 0, 0, 0, boss_card6);
    loop { wait(600); }
}
